import math
import json

# Model weights (fixed at training time)
A = 2.91983
B = 2.756296
C = 2.470743
D = -0.022418


def _trigram_weight(tri):
    o0, o1, o2 = (ord(ch) for ch in tri)
    return math.sin(A * o0 + B * o1 + C * o2 + D)


def score(text):
    """Log-likelihood of `text` under the trigram model."""
    ll = 0.0
    for i in range(len(text) - 2):
        ll += _trigram_weight(text[i:i + 3])
    return {"score": round(ll, 6)}


class Predictor:
    def __init__(self):
        """Initialize the predictor."""
        pass

    def predict(self, input_data):
        """Predict function that will be called by the deployment.

        Args:
            input_data: The input data - could be a dict with 'instances' key

        Returns:
            The score result as a dictionary
        """
        # Handle different input formats
        if isinstance(input_data, dict):
            # KServe format: {"instances": [[text]]}
            instances = input_data.get("instances", [])
            if instances and isinstance(instances, list) and len(instances) > 0:
                # Get the first instance
                first_instance = instances[0]
                if isinstance(first_instance, list) and len(first_instance) > 0:
                    text = first_instance[0]
                elif isinstance(first_instance, str):
                    text = first_instance
                else:
                    text = str(first_instance)
            else:
                text = str(input_data)
        else:
            text = str(input_data)

        result = score(text)
        return result
